actions.script:
def _valid = ['kpis','movement','bydept','okrs']
def _clean = ((context.order ?: '').toString().split(',') as List).findAll { _valid.contains(it) }
ec.user.setPreference('HR_DASH_ORDER', _clean.join(','))
if (context.sizes != null) {
    def _sz = ((context.sizes ?: '').toString().split(',') as List)
            .collect { it.split(':') as List }
            .findAll { it.size()==2 && _valid.contains(it[0]) && it[1]=='half' }
            .collect { it[0]+':half' }
    ec.user.setPreference('HR_DASH_SIZE', _sz.join(','))
}
ec.web.sendJsonResponse([saved:true, order:_clean.join(',')])

import org.moqui.entity.EntityCondition
def ef = ec.entity

// ----- Roster (org-scoped) -----
// NOTE: wrap in a plain ArrayList — a Moqui EntityList overrides findAll/count with methods that
// CAST the closure result to Boolean (so a truthy-Date closure throws ClassCastException). A plain
// ArrayList uses GDK semantics (Groovy truthiness), which is what these closures rely on.
def emps = new ArrayList(orgId ? ef.find("zenith.erp.hr.Employee").condition("organizationPartyId", orgId).list() : [])
headcount = emps.size()
def _activeSet = ['EmpActive','EmpProbation','EmpNoticeperiod'] as Set
activeCount = emps.count { _activeSet.contains(it.statusId) }
deptCount = orgId ? ef.find("zenith.erp.hr.Department").condition("organizationPartyId", orgId).count() : 0

def _exd = { e -> e.relievingDate ?: e.lastWorkingDate ?: e.resignationDate }
def hires = emps.findAll { it.joiningDate != null }
def exits = emps.findAll { _exd(it) != null }

// ===== ZE-DASH date-range filter + Hires & Exits time series =====
// The range drives ONLY the movement chart + the New Hires / Exits KPI counts.
// Headcount / Active / Departments are point-in-time (current roster) — no range effect.
def _sdf = new java.text.SimpleDateFormat("yyyy-MM-dd")
_sdf.setTimeZone(ec.user.timeZone)
def _now = ec.user.nowTimestamp
def _todayStr = _sdf.format(_now)
if (!dashDate) dashDate = dashDateTo ?: (dateMode == 'all' ? '' : _todayStr)
if (!dashDateTo) dashDateTo = dashDate
dayStart = null; dayEndExcl = null
if (dashDate) {
    if (!dashDateTo) dashDateTo = dashDate
    if (dashDateTo < dashDate) { def _s = dashDate; dashDate = dashDateTo; dashDateTo = _s }
    dayStart = java.sql.Timestamp.valueOf(dashDate + " 00:00:00")
    def _ce = java.util.Calendar.getInstance(); _ce.setTime(java.sql.Timestamp.valueOf(dashDateTo + " 00:00:00")); _ce.add(java.util.Calendar.DAY_OF_MONTH, 1)
    dayEndExcl = new java.sql.Timestamp(_ce.getTimeInMillis())
}
def _cw = java.util.Calendar.getInstance(ec.user.timeZone); _cw.setTime(_now); _cw.set(java.util.Calendar.DAY_OF_WEEK, _cw.getFirstDayOfWeek()); def _weekStartStr = _sdf.format(_cw.getTime())
def _cm = java.util.Calendar.getInstance(ec.user.timeZone); _cm.setTime(_now); _cm.set(java.util.Calendar.DAY_OF_MONTH,1); def _monthStartStr = _sdf.format(_cm.getTime())
def _c30 = java.util.Calendar.getInstance(ec.user.timeZone); _c30.setTime(_now); _c30.add(java.util.Calendar.DAY_OF_MONTH,-29); def _last30Str = _sdf.format(_c30.getTime())
urlAll = "?dateMode=all"; urlToday = "?dashDate="+_todayStr+"&dashDateTo="+_todayStr
urlWeek = "?dashDate="+_weekStartStr+"&dashDateTo="+_todayStr
urlMonth = "?dashDate="+_monthStartStr+"&dashDateTo="+_todayStr
url30 = "?dashDate="+_last30Str+"&dashDateTo="+_todayStr
presetActive = 'all'
if (dashDate) {
    presetActive = 'custom'
    if (dashDateTo == _todayStr) {
        if (dashDate == _todayStr) presetActive='today'
        else if (dashDate == _weekStartStr) presetActive='week'
        else if (dashDate == _monthStartStr) presetActive='month'
        else if (dashDate == _last30Str) presetActive='last30'
    }
}
// ZE-DATEWISE: This Year preset + "Date-wise" custom-range tab (self-contained; var-name-agnostic)
def _dwSdf = _sdf; def _dwNow = _now; def _dwToday = _todayStr
def _dwYc = java.util.Calendar.getInstance(ec.user.timeZone); _dwYc.setTime(_dwNow); _dwYc.set(java.util.Calendar.MONTH,0); _dwYc.set(java.util.Calendar.DAY_OF_MONTH,1); def _dwYearStart = _dwSdf.format(_dwYc.getTime())
urlYear = "?dateMode=year&dashDate="+_dwYearStart+"&dashDateTo="+_dwToday
if (dashDate && dashDateTo == _dwToday && dashDate == _dwYearStart && (dateMode == 'year' || presetActive != 'today')) presetActive = 'year'
showCustom = (((dateMode ?: '') == 'custom') || (presetActive == 'custom'))
urlCustom = dashDate ? ("?dateMode=custom&dashDate="+dashDate+"&dashDateTo="+dashDateTo) : "?dateMode=custom"
def _mvStart; def _mvEnd
if (dayStart) { _mvStart = dayStart; _mvEnd = dayEndExcl }
else {
    def _c6 = java.util.Calendar.getInstance(); _c6.setTime(_now); _c6.set(java.util.Calendar.DAY_OF_MONTH,1); _c6.add(java.util.Calendar.MONTH,-5)
    _c6.set(java.util.Calendar.HOUR_OF_DAY,0); _c6.set(java.util.Calendar.MINUTE,0); _c6.set(java.util.Calendar.SECOND,0); _c6.set(java.util.Calendar.MILLISECOND,0)
    _mvStart = new java.sql.Timestamp(_c6.getTimeInMillis())
    def _ce2 = java.util.Calendar.getInstance(); _ce2.setTime(_now); _ce2.add(java.util.Calendar.DAY_OF_MONTH,1); _mvEnd = new java.sql.Timestamp(_ce2.getTimeInMillis())
}
def _inWin = { d -> d != null && d.getTime() >= _mvStart.getTime() && d.getTime() < _mvEnd.getTime() }
def _daily = ((_mvEnd.getTime() - _mvStart.getTime()) / (1000L*60*60*24)) <= 62
def _bfmt = _daily ? new java.text.SimpleDateFormat("yyyy-MM-dd") : new java.text.SimpleDateFormat("yyyy-MM")
def _lfmt = _daily ? new java.text.SimpleDateFormat("dd MMM") : new java.text.SimpleDateFormat("MMM yy")
def _keys = []; def _labelByKey = [:]; def _hireBy = [:]; def _exitBy = [:]
def _bc = java.util.Calendar.getInstance(); _bc.setTime(_mvStart); def _bendMs = _mvEnd.getTime(); int _guard = 0
while (_bc.getTimeInMillis() < _bendMs && _guard < 400) {
    def _k = _bfmt.format(_bc.getTime())
    if (!_labelByKey.containsKey(_k)) { _keys.add(_k); _labelByKey[_k] = _lfmt.format(_bc.getTime()); _hireBy[_k]=0; _exitBy[_k]=0 }
    _bc.add(_daily ? java.util.Calendar.DAY_OF_MONTH : java.util.Calendar.MONTH, 1); _guard++
}
hires.each { if (_inWin(it.joiningDate)) { def _k = _bfmt.format(it.joiningDate); if (_hireBy.containsKey(_k)) _hireBy[_k] = _hireBy[_k] + 1 } }
exits.each { def _d = _exd(it); if (_inWin(_d)) { def _k = _bfmt.format(_d); if (_exitBy.containsKey(_k)) _exitBy[_k] = _exitBy[_k] + 1 } }
def _mlbls=[]; def _mhire=[]; def _mexit=[]
_keys.each { _k -> _mlbls.add("'"+_labelByKey[_k]+"'"); _mhire.add(_hireBy[_k]); _mexit.add(_exitBy[_k]) }
mvLabelsJson = "["+_mlbls.join(",")+"]"; mvHireJson = "["+_mhire.join(",")+"]"; mvExitJson = "["+_mexit.join(",")+"]"
mvHireCount = hires.count { _inWin(it.joiningDate) }
mvExitCount = exits.count { _inWin(_exd(it)) }
mvHasData = (mvHireCount + mvExitCount) > 0
mvRangeLabel = dashDate ? (dashDate == dashDateTo ? dashDate : (dashDate + " to " + dashDateTo)) : "last 6 months"
// KPI counts match the chart window exactly (range, else last 6 months) so tile and chart agree.
newHires = mvHireCount
exitCount = mvExitCount

// ----- Employees by department (top 8) -----
def deptList = new ArrayList(orgId ? ef.find("zenith.erp.hr.Department").condition("organizationPartyId", orgId).list() : [])
def _deptName = [:]; deptList.each { _deptName[it.departmentId] = it.departmentName }
def _byDept = [:]
emps.each { def dn = (_deptName[it.departmentId] ?: 'Unassigned').toString(); _byDept[dn] = (_byDept[dn] ?: 0) + 1 }
def _dpairs = _byDept.entrySet().toList(); _dpairs.sort { a, b -> (b.value <=> a.value) }
if (_dpairs.size() > 8) _dpairs = _dpairs.subList(0, 8)
def _dlbls=[]; def _dvals=[]
_dpairs.each { e -> def nm = e.key.toString().replace("'"," ").replace("\""," "); if (nm.length()>24) nm = nm.substring(0,24); _dlbls.add("'"+nm+"'"); _dvals.add(e.value.toString()) }
deptLabelsJson = "["+_dlbls.join(",")+"]"; deptValsJson = "["+_dvals.join(",")+"]"
deptHasData = (_dvals.size() > 0)

// ----- Active OKRs (org-scoped via the org's employees) -----
def _empIds = emps.collect { it.employeeId }
if (!_empIds) _empIds = ['__NONE__']
objectives = ef.find("zenith.erp.hr.OkrObjective").condition("employeeId", EntityCondition.IN, _empIds).orderBy("-progressPercent").limit(12).list()

// ZE-DASH layout: switchable widgets (+ cashier role default) + saved drag order
def _roleHidden = ''
try {
    if (!ec.user.isInGroup("ADMIN")) {
        def _zrp = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        if (_zrp.size() == 1 && _zrp.contains("ZENITH_CASHIER")) _roleHidden = 'movement,bydept,okrs'
    }
} catch (Exception e) {}
def _pref = ec.user.getPreference('HR_DASH_HIDDEN')
def _hiddenSet = ((_pref != null) ? _pref : _roleHidden).split(',').findAll { it }.toSet()
showKpis = !_hiddenSet.contains('kpis'); showMovement = !_hiddenSet.contains('movement')
showBydept = !_hiddenSet.contains('bydept'); showOkrs = !_hiddenSet.contains('okrs')
w_kpis = showKpis ? 'Y' : ''; w_movement = showMovement ? 'Y' : ''
w_bydept = showBydept ? 'Y' : ''; w_okrs = showOkrs ? 'Y' : ''
dashOrderCsv = (ec.user.getPreference('HR_DASH_ORDER') ?: '')
dashSizeCsv = (ec.user.getPreference('HR_DASH_SIZE') ?: '')
urlSettings = dashDate ? ("?dashDate="+dashDate+"&dashDateTo="+dashDateTo+"&showSettings=1") : "?showSettings=1"
